1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	}
8	
9	const PROCESSING_FEE = 5;
10	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
11	
12	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
13	  sword: 100,
14	  amulet: 60,
15	  staff: 80,
16	  potion: 40,
17	};
18	
19	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
20	const COMPONENT_BASE_PREMIUM = 25;
21	const BLOCK_SIZE = 3;
22	const BLOCK_BASE_PREMIUM = 60;
23	
24	function isComponent(item: Item): boolean {
25	  return COMPONENT_TYPES.has(item.type);
26	}
27	
28	function alikeComponentGroupSizes(components: Item[]): number[] {
29	  const sizePerType = new Map<string, number>();
30	  for (const component of components) {
31	    sizePerType.set(component.type, (sizePerType.get(component.type) ?? 0) + 1);
32	  }
33	  return [...sizePerType.values()];
34	}
35	
36	function alikeComponentGroupBasePremium(groupSize: number): number {
37	  return groupSize === BLOCK_SIZE
38	    ? BLOCK_BASE_PREMIUM
39	    : groupSize * COMPONENT_BASE_PREMIUM;
40	}
41	
42	function componentsBasePremium(components: Item[]): number {
43	  return alikeComponentGroupSizes(components)
44	    .map(alikeComponentGroupBasePremium)
45	    .reduce((sum, premium) => sum + premium, 0);
46	}
47	
48	function mainItemsBasePremium(mainItems: Item[]): number {
49	  return mainItems
50	    .map((mainItem) => MAIN_ITEM_BASE_PREMIUMS[mainItem.type])
51	    .reduce((sum, premium) => sum + premium, 0);
52	}
53	
54	function policyBasePremium(items: Item[]): number {
55	  return (
56	    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
57	    componentsBasePremium(items.filter(isComponent))
58	  );
59	}
60	
61	function firstInsuranceSurcharge(basePremium: number): number {
62	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
63	}
64	
65	function premiumRoundedInMhpcosFavor(premium: number): number {
66	  return Math.ceil(premium);
67	}
68	
69	export function quote(
70	  customer: Customer,
71	  items: Item[],
72	  previousContracts: number,
73	): number {
74	  const basePremium = policyBasePremium(items);
75	  const premium =
76	    basePremium + firstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
77	  return premiumRoundedInMhpcosFavor(premium);
78	}
